// Parse the JSON response body
const jsonData = pm.response.json();

// Check if the response contains the expected data and set the collection variables
if (jsonData.accessToken) {
    pm.collectionVariables.set("jwt_access", jsonData.accessToken);
}

if (jsonData.refreshToken) {
    pm.collectionVariables.set("jwt_refresh", jsonData.refreshToken);
}

if (jsonData.organization && jsonData.organization.id) {
    pm.collectionVariables.set("org_id", jsonData.organization.id);
}

// Optional: Add a quick test to verify the variables were extracted successfully in the Test Results tab
pm.test("Auth and Org variables set successfully", function () {
    pm.expect(pm.collectionVariables.get("jwt_access")).to.not.be.undefined;
    pm.expect(pm.collectionVariables.get("jwt_refresh")).to.not.be.undefined;
    pm.expect(pm.collectionVariables.get("org_id")).to.not.be.undefined;
});

